package ncasa.shoppinglist.application;
import java.time.Clock;import java.util.*;import ncasa.shoppinglist.application.port.out.*;import ncasa.shoppinglist.domain.*;
public final class AddShoppingItemUseCase{private final ShoppingListRepository lists;private final ShoppingItemRepository items;private final ShoppingListHouseholdAccessPort access;private final Clock clock;public AddShoppingItemUseCase(ShoppingListRepository l,ShoppingItemRepository i,ShoppingListHouseholdAccessPort a,Clock c){lists=l;items=i;access=a;clock=c;}public ShoppingItem execute(Long actor,UUID household,UUID listId,ShoppingItemCommand command){var ctx=access.getContext(household,actor);ctx.requireActive(command.responsibleMemberId());var list=GetShoppingListUseCase.load(lists,listId,household);list.requireActive();var item=ShoppingItem.create(UUID.randomUUID(),listId,command.name(),command.quantity(),command.unit(),command.customUnit(),command.note(),command.responsibleMemberId(),ctx.actorMemberId(),items.nextPendingPosition(listId),clock.instant());var saved=items.save(item);lists.touchContent(listId,clock.instant());return saved;}}
